var e={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Temukan aliran volumetrik tertinggi (mm³/s) yang dapat dipertahankan hotend Anda - dengan menaikkan aliran sambil mengawasi pembacaan beban StallGuard ekstruder untuk mendeteksi saat gigi tergelincir. Pratinjau rencana terlebih dahulu; uji langsung memanaskan dan mengekstrusi, jadi siapkan printer sebelum menjalankannya.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Bantuan`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tentang Max-Flow`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Tutup`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Cara penggunaan`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Atur suhu uji dan diameter filamen Anda (pilih hotend untuk mengisi otomatis).`}},{t:0,b:{t:2,i:[{t:3}],s:`Pratinjau rencana - menampilkan setiap langkah aliran dan berapa banyak filamen yang didorong.`}},{t:0,b:{t:2,i:[{t:3}],s:`Centang daftar keselamatan, lalu jalankan uji langsung (memanaskan + mengekstrusi).`}},{t:0,b:{t:2,i:[{t:3}],s:`Baca aliran berkelanjutan maksimum dan salin nilai slicer yang disarankan.`}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cara kerja uji`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ekstruder mendorong filamen pada aliran volumetrik yang terus meningkat. Selama gigi bergerigi mencengkeram dengan baik, pembacaan beban StallGuard tetap rapat; begitu mulai tergelincir, pembacaan akan melonjak tak menentu. Aliran tertinggi yang dicapai sebelum lonjakan itu adalah aliran maksimum berkelanjutan Anda. Kenaikan berhenti segera setelah selip terdeteksi, jadi tidak ada filamen yang tergerus melewati selip pertama.`}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:`Deteksi selip StallGuard`}},body:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard adalah fitur driver TMC yang melaporkan beban motor. Uji ini mengambil sampelnya berkali-kali per langkah aliran dan mencari kenaikan mendadak pada sebaran (IQR) atau variasi (CV) - tanda gigi kehilangan cengkeraman. Ambang batas berasal dari profil per-driver. Catatan: pada ekstruder TMC2209 ini menggunakan jalur eksperimental SG4, jadi perlakukan jalannya yang pertama sebagai kalibrasi.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Keselamatan`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ini adalah uji yang panas dan bergerak yang sengaja membuat ekstruder tergelincir. Muat filamen, pastikan nozel bersih (di atas bed atau area buangan), dan tetaplah di dekatnya. Uji ditolak saat printer sedang mencetak, dan pemanas selalu dimatikan saat selesai.`}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:`Menggunakan hasil`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Masukkan nilai yang disarankan ke "max volumetric speed" pada slicer Anda (per filamen). Angka konservatif (80% dari maksimum terukur) adalah batas harian yang aman; angka seimbang (90%) mendorong sedikit lebih keras. Suhu hotend yang lebih tinggi biasanya menaikkan aliran yang dapat dicapai.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosarium`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:`Aliran volumetrik`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Berapa banyak plastik yang dilelehkan hotend per detik (mm³/s) - batas kecepatan sebenarnya untuk pencetakan cepat.`}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Sinyal driver TMC yang melaporkan beban mekanis motor, digunakan di sini untuk mendeteksi selip ekstruder.`}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:`Selip`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Saat gigi ekstruder tidak lagi dapat mencengkeram filamen cukup cepat sehingga melompat - batas atas aliran.`}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:`Zona leleh`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Panjang bagian hotend yang dipanaskan; zona leleh yang lebih panjang (mis. Volcano) mempertahankan aliran lebih tinggi.`}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:`Parameter uji`}},temperature:{t:0,b:{t:2,i:[{t:3}],s:`Suhu (°C)`}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:`Ø Filamen (mm)`}},hotend:{t:0,b:{t:2,i:[{t:3}],s:`Hotend (opsional)`}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:`- tidak ada -`}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:`Diperkirakan ~`},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:`Aliran awal (mm³/s)`}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:`Aliran akhir (mm³/s)`}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:`Langkah (mm³/s)`}},samples:{t:0,b:{t:2,i:[{t:3}],s:`Sampel / langkah`}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:`Ekstrusi / langkah (mm)`}},driver:{t:0,b:{t:2,i:[{t:3}],s:`Driver ekstruder`}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:`terdeteksi dari printer`}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:`Aktifkan StealthChop otomatis untuk uji`}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:`Hanya TMC2209/2240: menulis stealthchop_threshold sementara ke ekstruder agar StallGuard dapat membaca, lalu menonaktifkannya dengan komentar setelah uji. Memulihkan printer.cfg; firmware restart di kedua arah.`}},method:{t:0,b:{t:2,i:[{t:3}],s:`Metode deteksi`}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:`Auto menggunakan StallGuard, beralih ke akselerometer toolhead (getaran) saat StallGuard tidak dapat membaca. Metode akselerometer bersifat eksperimental.`}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:`Auto`}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},accel:{t:0,b:{t:2,i:[{t:3}],s:`Akselerometer`}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:`Pratinjau rencana`}},title:{t:0,b:{t:2,i:[{t:3}],s:`Kenaikan terencana`}},stepCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` langkah`}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:`mm`},{t:3,v:` mm filamen`}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:`Bidang StallGuard: `},{t:4,k:`field`}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada bidang StallGuard yang dikenal untuk driver ini`}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:`Aliran (mm³/s)`}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:`Feedrate (mm/min)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`Uji langsung memanaskan hotend dan mengekstrusi filamen, sengaja hingga titik selip. Hanya pratinjau - belum ada yang berjalan.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sebelum menjalankan - daftar keselamatan`}},items:[{t:0,b:{t:2,i:[{t:3}],s:`Filamen sudah dimuat dan mengalir dengan lancar.`}},{t:0,b:{t:2,i:[{t:3}],s:`Nozel bersih - di atas bed atau tempat buangan, tidak menggantung ke arah komponen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Saya menerima bahwa ini akan sengaja menggerus/menggelincirkan sebagian filamen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Saya akan tetap berada di dekat printer selama uji berlangsung.`}}],ack:{t:0,b:{t:2,i:[{t:3}],s:`Saya telah melakukan semua hal di atas dan printer siap`}},note:{t:0,b:{t:2,i:[{t:3}],s:`Uji ditolak saat mencetak; pemanas dimatikan otomatis di akhir.`}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:`Jalankan uji langsung`}},running:{t:0,b:{t:2,i:[{t:3}],s:`Berjalan… (memanaskan + mengekstrusi)`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Mulai uji max-flow langsung?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`Ini memanaskan hotend hingga `},{t:4,k:`temp`},{t:3,v:` °C dan mengekstrusi hingga `},{t:4,k:`mm`},{t:3,v:` mm filamen, menaikkan aliran sampai ekstruder tergelincir.`}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Jalankan sekarang`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Batal`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Ditolak: printer sedang sibuk (mencetak atau dijeda). Coba lagi saat sedang menganggur.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Uji gagal.`}},noSg:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada sampel StallGuard yang terbaca - hasil selip mungkin tidak dapat diandalkan. Bidang SG langsung driver kemungkinan perlu disesuaikan untuk model ini.`}},progress:{t:0,b:{t:2,i:[{t:3,v:`Langkah `},{t:4,k:`step`},{t:3,v:`/`},{t:4,k:`total`},{t:3,v:` - `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:`Memanaskan / memulai…`}},abort:{t:0,b:{t:2,i:[{t:3}],s:`Hentikan uji`}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:`Menghentikan…`}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:`Uji dihentikan - pemanas telah dimatikan.`}},reattached:{t:0,b:{t:2,i:[{t:3}],s:`Tersambung kembali: hasil ini selesai saat halaman tidak aktif.`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Uji max-flow gagal.`}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:`Menghentikan selalu mematikan pemanas.`}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:`Sebelum memanaskan, printer melakukan homing (jika perlu) dan memposisikan nozel di tengah untuk tampilan yang jelas.`}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:`Mengaktifkan StealthChop…`}},homing:{t:0,b:{t:2,i:[{t:3}],s:`Melakukan homing printer…`}},centering:{t:0,b:{t:2,i:[{t:3}],s:`Memposisikan nozel di tengah…`}},heating:{t:0,b:{t:2,i:[{t:3}],s:`Memanaskan hotend…`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Memeriksa sinyal StallGuard…`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`Menaikkan aliran…`}},reverting:{t:0,b:{t:2,i:[{t:3}],s:`Memulihkan konfigurasi…`}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:`Home`}},center:{t:0,b:{t:2,i:[{t:3}],s:`Tengah`}},heat:{t:0,b:{t:2,i:[{t:3}],s:`Panaskan`}},check:{t:0,b:{t:2,i:[{t:3}],s:`Periksa`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`Naikkan`}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:`Kamera langsung`}},live:{t:0,b:{t:2,i:[{t:3}],s:`LANGSUNG`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Kamera tidak tersedia.`}},willShow:{t:0,b:{t:2,i:[{t:3}],s:`Tampilan kamera langsung akan menampilkan nozel selama uji.`}},minimize:{t:0,b:{t:2,i:[{t:3}],s:`Minimalkan`}},maximize:{t:0,b:{t:2,i:[{t:3}],s:`Maksimalkan`}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:`Perbesar`}},shrink:{t:0,b:{t:2,i:[{t:3}],s:`Perkecil`}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:`Hasil`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Aliran berkelanjutan maksimum`}},slipAt:{t:0,b:{t:2,i:[{t:3,v:`Selip terdeteksi pada `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada selip hingga aliran tertinggi yang diuji`}},reason:{t:0,b:{t:2,i:[{t:3}],s:`Detail`}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:`Nilai slicer yang disarankan (max volumetric speed)`}},conservative:{t:0,b:{t:2,i:[{t:3}],s:`Konservatif (80%)`}},balanced:{t:0,b:{t:2,i:[{t:3}],s:`Seimbang (90%)`}},units:{t:0,b:{t:2,i:[{t:3}],s:`mm³/s`}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:`Diukur sebelumnya (`},{t:4,k:`at`},{t:3,v:`) - jalankan lagi untuk angka terbaru.`}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tidak andal - tidak ada sinyal StallGuard`}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:`tercapai, tidak terkonfirmasi`}},via:{t:0,b:{t:2,i:[{t:3,v:`Diukur melalui `},{t:4,k:`method`}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:`Diukur dengan getaran (akselerometer) - eksperimental; perlakukan angkanya sebagai panduan, bukan batas atas yang pasti.`}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:`Memuat hotend…`}}}}};export{e as default};